UPDATE knowledge_index_version i
SET status = #{deletedStatus}, update_time = NOW()
WHERE i.id = #{id}
  AND i.status != #{deletedStatus}
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_info k
      WHERE k.id = i.knowledge_id
        AND k.current_index_version = i.index_version
  )
  AND (
      i.status != #{activeStatus}
      OR NOT EXISTS (
          SELECT 1 FROM knowledge_index_document d
          WHERE d.index_version_id = i.id
      )
  )
  AND NOT EXISTS (
      SELECT 1 FROM knowledge_parse_job j
      WHERE j.knowledge_id = i.knowledge_id
        AND j.target_index_version = i.index_version
        AND j.status IN

            #{status}

  )

